INSERT OR IGNORE INTO courses(id,category_id,data,published,featured,position,updated_at) VALUES ('ai-starter','category-1','{"id":"ai-starter","stage":0,"category":"AI 入門","title":"AI 不難，從你的第一個好問題開始","subtitle":"AI 入門 × 提示設計 × 日常效率","description":"不需要程式基礎。從清楚描述任務、補足情境到驗證答案，建立真正用得上的 AI 使用習慣。","instructor":"精五門教學團隊","duration":"3 小時 20 分","lessons":12,"price":1680,"coachingPrice":4880,"credits":2,"art":"prompt","color":"violet","badge":"新手首選","published":true,"outcomes":["寫出含情境與限制的提示","檢查 AI 回答的可靠性","完成一份自己的工作小助手模板"]}',1,1,0,0);
