INSERT OR IGNORE INTO courses(id,category_id,data,published,featured,position,updated_at) VALUES ('ai-foundations','category-2','{"id":"ai-foundations","stage":1,"category":"理論基礎","title":"看懂 AI 的底層邏輯，不再只會下指令","subtitle":"大型語言模型 × 資料 × AI 素養","description":"用直觀的案例理解模型如何學習、為什麼會出錯，以及什麼時候需要人類的判斷。","instructor":"精五門教學團隊","duration":"4 小時 10 分","lessons":16,"price":2280,"coachingPrice":5480,"credits":2,"art":"nodes","color":"blue","badge":"觀念打底","published":true,"outcomes":["理解生成模型的限制","區分訓練與推論","規劃資料品質與驗證方式"]}',1,1,1,0);
