INSERT OR IGNORE INTO courses(id,category_id,data,published,featured,position,updated_at) VALUES ('ai-workflows','category-3','{"id":"ai-workflows","stage":2,"category":"進階實作","title":"把重複工作交給 AI：打造你的自動化流程","subtitle":"工作流程 × API × 實戰專案","description":"把零散工具串成有輸入、驗證與錯誤處理的流程，做出一個實際可交付的小專案。","instructor":"精五門教學團隊","duration":"6 小時 30 分","lessons":24,"price":3280,"coachingPrice":6480,"credits":2,"art":"workflow","color":"pink","badge":"實作推薦","published":true,"outcomes":["設計多步驟工作流程","串接 API 與結構化輸出","處理失敗、重試與人工確認"]}',1,1,2,0);
