INSERT OR IGNORE INTO courses(id,category_id,data,published,featured,position,updated_at) VALUES ('ai-developer','category-4','{"id":"ai-developer","stage":3,"category":"AI 開發","title":"從零到作品：開發你的第一個 AI 應用","subtitle":"程式開發 × RAG × 評估與部署","description":"讓原型走向可靠的應用。從資料檢索到金鑰管理，用測試與評估驗證產品是否真的有用。","instructor":"精五門教學團隊","duration":"8 小時 15 分","lessons":32,"price":4280,"coachingPrice":7480,"credits":2,"art":"code","color":"purple","badge":"挑戰進階","published":true,"outcomes":["建立具檢索能力的 AI 應用","保護伺服器端密鑰","建立測試集並部署作品"]}',1,1,3,0);
